CHUNK({"chunk":"M","module":"m4","topics":[{"id":"m4-water-act-basics","title":"Water Act, 1974: background and boards","short":"Water Act basics","blurb":"Why the Water Act came, its constitutional basis under Article 252, the 1988 amendment, the seven needs it meets, and the CPCB, SPCBs and Joint Boards it created.","source":"Lecture W4 (Water Act, Part II), pages 1–3","tabs":[{"title":"Background","html":"\n          <p class=\"lead\"><b>Water (Prevention and Control of Pollution) Act, 1974</b>: India's <b>first comprehensive water pollution law</b>, <b>23 March 1974</b>; aim: restore <b>wholesomeness</b> of water.</p>\n          <ul>\n            <li><b>Article 252</b>: Parliament legislates on a <b>state subject</b> (water) at states' request.</li>\n            <li><b>1988 amendment</b>: higher penalties, wider Board powers.</li>\n            <li><b>64 sections, 10 chapters</b>.</li>\n          </ul>\n          <p>Seven needs: public health, aquatic life, future generations, economics, <b>uniform national standards</b>, expertise, international obligations.</p>\n        "},{"title":"Boards","html":"\n          <table class=\"tbl\">\n            <tbody>\n              <tr><td><b>Section 3</b></td><td><b>CPCB</b> (national): advises Centre, coordinates SPCBs, national standards</td></tr>\n              <tr><td><b>Section 4</b></td><td><b>SPCB</b> (state): consent, monitoring, labs, prosecution</td></tr>\n              <tr><td><b>Section 13</b></td><td><b>Joint Board</b>: two or more states (inter-state rivers)</td></tr>\n              <tr><td><b>Section 18</b></td><td>Boards give <b>binding directions</b></td></tr>\n            </tbody>\n          </table>\n          <p>The Water Act <b>created the CPCB and SPCBs</b>.</p>\n        "}],"flashcards":[{"front":"Date the Water Act was enacted?","back":"<b>23 March 1974</b>."},{"front":"Constitutional basis of the Water Act?","back":"<b>Article 252</b>: Parliament legislates on a state subject at states' request."},{"front":"Which law created the CPCB and SPCBs?","back":"The <b>Water Act, 1974</b>."}],"cardCount":6,"formulaCount":0},{"id":"m4-water-act-provisions","title":"Water Act: key provisions","short":"Water Act provisions","blurb":"Sections 24, 25 and 26 on discharge, sections 21 and 23 on sampling and entry, consent and MINAS, emergency powers, and appeals to the NGT.","source":"Lecture W4 (Water Act, Part II), pages 3–5, 9–10","tabs":[{"title":"Discharge and consent","html":"\n          <table class=\"tbl\">\n            <tbody>\n              <tr><td><b>Section 24</b></td><td><b>Absolute prohibition</b>: no polluting matter into a <b>stream or well</b></td></tr>\n              <tr><td><b>Section 25</b></td><td><b>Consent for new outlets</b></td></tr>\n              <tr><td><b>Section 26</b></td><td><b>Existing discharges</b>: consent by deadline</td></tr>\n              <tr><td><b>Section 27</b></td><td><b>Revocation</b> of consent</td></tr>\n            </tbody>\n          </table>\n          <p><b>MINAS</b> = <b>Minimum National Standards</b> for effluent, set by CPCB; states may be stricter.</p>\n        "},{"title":"Inspection and appeals","html":"\n          <table class=\"tbl\">\n            <tbody>\n              <tr><td><b>Section 21</b></td><td><b>Effluent samples</b></td></tr>\n              <tr><td><b>Section 23</b></td><td><b>Entry and inspection</b></td></tr>\n              <tr><td><b>Section 32</b></td><td><b>Emergency measures</b></td></tr>\n              <tr><td><b>Section 33</b></td><td>Boards apply to <b>courts</b> to stop apprehended pollution</td></tr>\n              <tr><td><b>Section 28 / 29</b></td><td>Appeal to / revision by State Govt</td></tr>\n              <tr><td><b>Section 33B</b></td><td>Appeal to <b>NGT</b> (set up <b>2010</b>)</td></tr>\n            </tbody>\n          </table>\n        "}],"flashcards":[{"front":"Water Act section with the absolute ban on polluting streams and wells?","back":"<b>Section 24</b>."},{"front":"Water Act section for consent for new outlets?","back":"<b>Section 25</b>."},{"front":"Section 26 covers…","back":"<b>Existing</b> discharges, which must seek consent by a deadline."}],"cardCount":6,"formulaCount":0},{"id":"m4-water-act-penalties","title":"Water Act penalties and the three Acts compared","short":"Water Act penalties","blurb":"Penalty sections 41 to 47, key features of offences, why engineers must know the Act, and a quick reference for EPA, Air Act and Water Act.","source":"Lecture W4 (Water Act, Part II), pages 5–10","tabs":[{"title":"Penalties","html":"\n          <table class=\"tbl\">\n            <thead><tr><th>Section</th><th>Violation</th><th>Penalty</th></tr></thead>\n            <tbody>\n              <tr><td>41, 41A, 44</td><td>Board directions, court orders, no consent</td><td><b>1.5–6 years</b> + fine</td></tr>\n              <tr><td>42</td><td>Obstructing officers</td><td>Up to <b>3 months</b> or <b>₹10,000</b></td></tr>\n              <tr><td><b>43</b></td><td>Breaking Section 24</td><td>1.5–6 years (<b>most severe</b>)</td></tr>\n              <tr><td>45</td><td>Continuing</td><td><b>₹5,000 per day</b></td></tr>\n              <tr><td>46</td><td><b>Companies</b></td><td>Directors, managers, engineers liable</td></tr>\n              <tr><td>47</td><td><b>Govt departments</b></td><td><b>Head of Department</b></td></tr>\n            </tbody>\n          </table>\n          <p><b>Non-compoundable</b> (court mandatory); some <b>cognizable</b> (arrest without warrant). Fines go to the <b>Environmental Protection Fund</b>.</p>\n        "},{"title":"Three Acts compared","html":"\n          <table class=\"tbl\">\n            <thead><tr><th></th><th>Water Act 1974</th><th>Air Act 1981</th><th>EPA 1986</th></tr></thead>\n            <tbody>\n              <tr><td>Amended</td><td>1988</td><td>1987 (noise)</td><td>After Bhopal</td></tr>\n              <tr><td>Penalty</td><td><b>1.5–6 years</b></td><td><b>3 months + ₹10,000</b></td><td><b>5 years + ₹1 lakh</b> (7 if continued)</td></tr>\n            </tbody>\n          </table>\n          <p>Engineers: <b>zero liquid discharge</b>; personal liability under <b>Section 46</b>.</p>\n        "}],"flashcards":[{"front":"Water Act imprisonment range for serious violations?","back":"<b>1.5 to 6 years</b> plus fine."},{"front":"Section for continuing violation fines?","back":"<b>Section 45</b>: up to <b>₹5,000 per day</b>."},{"front":"Most severe penalty section?","back":"<b>Section 43</b>, for breaking Section 24."}],"cardCount":6,"formulaCount":0}],"figures":[]});
